content:
780          }
   781
   782          if (parser) {
   783              parser_ctx = flb_parser_get(parser, config);
   784          }
   785          ml_parser = flb_ml_parser_create(config, name, type, match_string,
   786                                           negate, flush_timeout, key_content,
   787                                           key_group, key_pattern,
   788                                           parser_ctx, parser);
   789          if (!ml_parser) {
   790              goto fconf_error;
   791          }
   792
   793          /* if type is regex, process rules */
   794          if (type == FLB_ML_REGEX) {
   795              ret = multiline_load_regex_rules(ml_parser, s, config);
   796              if (ret != 0) {
   797                  goto fconf_error;
   798              }
   799          }
   800
   801          flb_sds_destroy(name);
   802          flb_sds_destroy(match_string);
   803          flb_sds_destroy(key_content);
   804          flb_sds_destroy(key_pattern);
   805          flb_sds_destroy(key_group);
   806          flb_sds_destroy(parser);
   807          flb_sds_destroy(tmp);
   808      }
   809
   810      return 0;
   811
   812   fconf_error:
   813      if (ml_parser) {
   814          flb_ml_parser_destroy(ml_parser);
   815      }
   816      flb_sds_destroy(name);
   817      flb_sds_destroy(match_string);
   818      flb_sds_destroy(key_content);
   819      flb_sds_destroy(key_pattern);
   820      flb_sds_destroy(key_group);
   821      flb_sds_destroy(parser);
   822      flb_sds_destroy(tmp);
   823
   824      return -1;
   825  }
