   827  /* Load parsers from a configuration file */
   828  int flb_parser_conf_file(const char *file, struct flb_config *config)
   829  {
   830      int ret;
   831      char tmp[PATH_MAX + 1];
   832      char *cfg = NULL;
   833      struct stat st;
   834      struct flb_cf *cf;
   835
   836  #ifndef FLB_HAVE_STATIC_CONF
   837      ret = stat(file, &st);
   838      if (ret == -1 && errno == ENOENT) {
   839          /* Try to resolve the real path (if exists) */
   840          if (file[0] == '/') {
   841              flb_utils_error(FLB_ERR_CFG_PARSER_FILE);
   842              return -1;
   843          }
   844
   845          if (config->conf_path) {
   846              snprintf(tmp, PATH_MAX, "%s%s", config->conf_path, file);
   847              cfg = tmp;
   848          }
   849      }
   850      else {
   851          cfg = (char *) file;
   852      }
   853
   854      cf = flb_cf_create_from_file(config->cf_parsers, cfg);
   855  #else
   856      cf = flb_config_static_open(file);
   857      if (cf) {
   858          if (config->cf_parsers) {
   859              flb_cf_destroy(config->cf_parsers);
   860          }
   861          config->cf_parsers = cf;
   862      }
   863  #endif
   864
   865      if (!cf) {
   866          return -1;
   867      }
   868
   869      /* process 'parser' sections */
   870      ret = parser_conf_file(cfg, cf, config);
   871      if (ret == -1) {
   872          return -1;
   873      }
   874
   875      /* processs 'multiline_parser' sections */
   876      ret = multiline_parser_conf_file(cfg, cf, config);
   877      if (ret == -1) {
   878          return -1;
   879      }
   880
   881      return 0;
   882  }
