   884  struct flb_parser *flb_parser_get(const char *name, struct flb_config *config)
   885  {
   886      struct mk_list *head;
   887      struct flb_parser *parser;
   888
   889      if (config == NULL || mk_list_size(&config->parsers) <= 0) {
   890          return NULL;
   891      }
   892
   893      mk_list_foreach(head, &config->parsers) {
   894          parser = mk_list_entry(head, struct flb_parser, _head);
   895          if (parser == NULL || parser->name == NULL) {
   896              continue;
   897          }
   898          if (strcmp(parser->name, name) == 0) {
   899              return parser;
   900          }
